#!/usr/bin/env python3
"""Lossless stdlib-only file compressor."""
import bz2
import sys


def compress(data):
    return b'CH1' + bz2.compress(data, compresslevel=9)


def decompress(data):
    if data[:3] != b'CH1':
        raise ValueError('invalid compressed file')
    return bz2.decompress(data[3:])


def main():
    args = sys.argv[1:]
    decode = bool(args and args[0] == '--decompress')
    if decode:
        args = args[1:]
    if len(args) != 2:
        raise SystemExit('usage: compress.py [--decompress] INPUT OUTPUT')
    with open(args[0], 'rb') as f:
        source = f.read()
    result = decompress(source) if decode else compress(source)
    with open(args[1], 'wb') as f:
        f.write(result)


if __name__ == '__main__':
    main()

